// Extrae wa_id, texto y opción de botón/lista del webhook de Meta.
const root = $input.first().json;
const body = root.body || root;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];

if (!msg) {
  // Puede ser un callback de estado (entregado/leído) -> ignorar
  return [{ json: { es_mensaje: false } }];
}

const wa_id = msg.from;
const profileName = value?.contacts?.[0]?.profile?.name || '';
let texto = '';
let opcion_id = '';

if (msg.type === 'text') {
  texto = msg.text?.body || '';
} else if (msg.type === 'interactive') {
  if (msg.interactive?.type === 'button_reply') {
    opcion_id = msg.interactive.button_reply.id || '';
    texto = msg.interactive.button_reply.title || '';
  } else if (msg.interactive?.type === 'list_reply') {
    opcion_id = msg.interactive.list_reply.id || '';
    texto = msg.interactive.list_reply.title || '';
  }
} else if (msg.type === 'button') {
  texto = msg.button?.text || '';
} else {
  texto = '[' + msg.type + ']';
}

const mensaje_para_agente = opcion_id ? (texto + ' (opcion_id: ' + opcion_id + ')') : texto;

return [{ json: { es_mensaje: true, wa_id, profileName, texto, opcion_id, mensaje_para_agente } }];

// Calcula momento del día y estado (abierto/cuando) de cada marca en America/Bogota.
const prev = $input.first().json;
const tz = 'America/Bogota';
const now = new Date();
const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: tz, hour12: false, weekday: 'long', hour: '2-digit', minute: '2-digit', month: 'numeric'
}).formatToParts(now);
const get = (t) => parts.find((x) => x.type === t)?.value;

const weekdayName = get('weekday');           // Monday ... Sunday
let hour = parseInt(get('hour'), 10); if (hour === 24) hour = 0;
const minute = parseInt(get('minute'), 10);
const mins = hour * 60 + minute;              // minutos desde medianoche
const mesNum = parseInt(get('month'), 10);
const dias = { Sunday: 0, Monday: 1, Tuesday: 2, Wednesday: 3, Thursday: 4, Friday: 5, Saturday: 6 };
const dow = dias[weekdayName];

const mesesEs = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const mes = mesesEs[mesNum - 1];

// Saludo
let momento = 'noche';
if (hour >= 5 && hour < 12) momento = 'mañana';
else if (hour >= 12 && hour < 19) momento = 'tarde';

function estado(marca) {
  // openStart/openEnd en minutos según marca y día; null = cerrado ese día
  let openStart = null, openEnd = null;
  if (marca === 'Ardisa') {
    if (dow >= 1 && dow <= 5) { openStart = 7 * 60 + 30; openEnd = 17 * 60; }   // 7:30-17:00
    else if (dow === 6)       { openStart = 8 * 60;       openEnd = 17 * 60; }   // sáb 8:00-17:00
  } else { // Carpincentro
    if (dow >= 1 && dow <= 5) { openStart = 8 * 60;       openEnd = 17 * 60; }   // 8:00-17:00
    else if (dow === 6)       { openStart = 8 * 60;       openEnd = 12 * 60; }   // sáb 8:00-12:00
  }

  const abierto = openStart !== null && mins >= openStart && mins < openEnd;

  let cuando;
  if (abierto) {
    cuando = 'ahora';
  } else if (dow === 0) {
    cuando = 'el lunes';
  } else if (dow === 6) {
    cuando = (openStart !== null && mins < openStart) ? 'hoy más tarde' : 'el lunes';
  } else if (dow === 5) {
    cuando = (mins < openStart) ? 'hoy más tarde' : 'el lunes';
  } else { // lunes a jueves
    cuando = (mins < openStart) ? 'hoy más tarde' : 'mañana';
  }

  return { abierto, cuando };
}

return [{ json: {
  ...prev,
  momento,
  mes,
  ardisa: estado('Ardisa'),
  carpincentro: estado('Carpincentro')
} }];

