// Parsea la salida del AI Agent: { reply, buttons?, lead? }
const ctx = $('Calcular horario').item.json;
let raw = ($json.output ?? '').toString().trim();

// Quitar fences de markdown si los hubiera
raw = raw.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

// Intentar aislar el primer objeto JSON
let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const a = raw.indexOf('{');
  const b = raw.lastIndexOf('}');
  if (a !== -1 && b !== -1 && b > a) {
    try { parsed = JSON.parse(raw.slice(a, b + 1)); } catch (e2) { parsed = null; }
  }
}

if (!parsed) {
  // Fallback: enviar el texto crudo como respuesta
  parsed = { reply: raw, buttons: [], lead: null };
}

const lead = (parsed.lead && typeof parsed.lead === 'object') ? parsed.lead : null;

return [{ json: {
  ...ctx,
  reply: parsed.reply || '',
  buttons: Array.isArray(parsed.buttons) ? parsed.buttons : [],
  lead,
  tiene_lead: !!lead
} }];

// Rama SIN lead: construye el cuerpo Graph API (texto o interactivo).
const j = $json;
const to = j.wa_id;
let body;

const btns = Array.isArray(j.buttons) ? j.buttons : [];

if (btns.length > 0 && btns.length <= 3) {
  body = {
    messaging_product: 'whatsapp', to, type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: (j.reply || '').slice(0, 1024) },
      action: { buttons: btns.slice(0, 3).map((b) => ({ type: 'reply', reply: { id: String(b.id).slice(0, 256), title: String(b.title).slice(0, 20) } })) }
    }
  };
} else if (btns.length > 3) {
  body = {
    messaging_product: 'whatsapp', to, type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: (j.reply || '').slice(0, 1024) },
      action: {
        button: 'Ver opciones',
        sections: [{ title: 'Opciones', rows: btns.slice(0, 10).map((b) => ({ id: String(b.id).slice(0, 200), title: String(b.title).slice(0, 24), description: (b.description || '').slice(0, 72) })) }]
      }
    }
  };
} else {
  body = { messaging_product: 'whatsapp', to, type: 'text', text: { body: (j.reply || '').slice(0, 4096) } };
}

return [{ json: { wa_id: to, to, wpp_body: body } }];

// Rama CON lead: busca asesor por (área + ciudad), arma cierre, SQL y aviso al asesor.
// ====== EDITAR: cargar ciudades reales y números (formato 57XXXXXXXXXX) ======
const DIRECTORIO = [
  { area: '1', asesor: 'Natalia Amaris Martínez',     numero: '57XXXXXXXXXX', ciudades: [/* TODO: ciudades */] },
  { area: '1', asesor: 'Pedro Jonathan López',         numero: '57XXXXXXXXXX', ciudades: [/* TODO: ciudades */] },
  { area: '1', asesor: 'Karina Núñez',                 numero: '57XXXXXXXXXX', ciudades: [/* TODO: ciudades */] },
  { area: '2', asesor: 'Miguel Ángel Barajas',         numero: '57XXXXXXXXXX', ciudades: [/* TODO: ciudades */] },
  { area: '2', asesor: 'Jhon Jairo Vargas Herreño',    numero: '57XXXXXXXXXX', ciudades: [/* TODO: ciudades */] },
  { area: '2', asesor: 'Yurmy Maíz Garza',             numero: '57XXXXXXXXXX', ciudades: [/* TODO: ciudades */] },
  { area: '3', asesor: 'Equipo Maderas (18 puntos)',   numero: '57XXXXXXXXXX', ciudades: ['Nacional'] }
];
// ============================================================================

const j = $json;
const lead = j.lead || {};
const wa_id = j.wa_id;

const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
const esc = (s) => (s == null ? '' : String(s)).replace(/'/g, "''");

const area = String(lead.area || '');
const ciudad = norm(lead.ciudad);

const match = DIRECTORIO.find((a) =>
  a.area === area &&
  (a.ciudades.some((c) => norm(c) === 'nacional') || a.ciudades.some((c) => norm(c) === ciudad))
);

let asesor_asignado, asesor_numero, estado_lead, asignado;
if (match) {
  asesor_asignado = match.asesor;
  asesor_numero = match.numero;
  estado_lead = 'pendiente';
  asignado = true;
} else {
  asesor_asignado = 'Sin asignar';
  asesor_numero = '';
  estado_lead = 'sin asignar';
  asignado = false;
}

const areaNombre = { '1': 'acabados y baño', '2': 'construcción y obra gris', '3': 'maderas y carpintería' }[area] || 'productos';

// Estado de la marca elegida para el cierre
const marca = lead.canal || 'Ardisa';
const h = (marca === 'Carpincentro') ? j.carpincentro : j.ardisa;
const cap = (s) => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;

let cierre;
if (!asignado) {
  cierre = 'Gracias, ' + (lead.nombre_cliente || '') + '. Tu solicitud quedó registrada y muy pronto un asesor se pondrá en contacto contigo. 🙌';
} else if (h && h.abierto) {
  cierre = 'Gracias, ' + lead.nombre_cliente + '. Tu solicitud quedó registrada. Tu asesor para ' + lead.ciudad + ' y la línea de ' + areaNombre + ' es ' + asesor_asignado + '. En unos momentos se pondrá en contacto contigo desde su WhatsApp. 🙌';
} else {
  cierre = 'Gracias, ' + lead.nombre_cliente + '. Tu solicitud quedó registrada. Tu asesor para ' + lead.ciudad + ' y la línea de ' + areaNombre + ' es ' + asesor_asignado + '. ' + cap(h ? h.cuando : 'pronto') + ' se pondrá en contacto contigo desde su WhatsApp. 🙌';
}

const wpp_body = { messaging_product: 'whatsapp', to: wa_id, type: 'text', text: { body: cierre } };

// Aviso interno al asesor (requiere ventana de 24h o plantilla aprobada)
const aviso =
  '🔔 *Nuevo lead ' + marca + '*\n' +
  '👤 ' + (lead.nombre_cliente || '') + '\n' +
  '📱 ' + wa_id + '\n' +
  '🏙️ ' + (lead.ciudad || '') + '\n' +
  '🧩 Tipo: ' + (lead.tipo_cliente || '') + '\n' +
  '🗂️ Área ' + area + ' – ' + areaNombre + '\n' +
  '🏷️ ' + (lead.clasificacion_01 || '') + '\n' +
  '📝 ' + (lead.solicitud_cliente || '');
const aviso_body = { messaging_product: 'whatsapp', to: asesor_numero, type: 'text', text: { body: aviso } };

// SQL escapado (evita inyección por comillas)
const sql =
  "INSERT INTO leads_whatsapp (mes, canal, area, nombre_cliente, celular, ciudad, clasificacion_01, tipo_cliente, solicitud_cliente, asesor_asignado, asesor_numero, estado, wa_id) VALUES (" +
  "'" + esc(j.mes) + "'," +
  "'" + esc(marca) + "'," +
  "'" + esc(area) + "'," +
  "'" + esc(lead.nombre_cliente) + "'," +
  "'" + esc(wa_id) + "'," +
  "'" + esc(lead.ciudad) + "'," +
  "'" + esc(lead.clasificacion_01) + "'," +
  "'" + esc(lead.tipo_cliente) + "'," +
  "'" + esc(lead.solicitud_cliente) + "'," +
  "'" + esc(asesor_asignado) + "'," +
  "'" + esc(asesor_numero) + "'," +
  "'" + esc(estado_lead) + "'," +
  "'" + esc(wa_id) + "')";

return [{ json: { wa_id, to: wa_id, wpp_body, aviso_body, sql, asignado, asesor_asignado, asesor_numero, estado_lead, marca } }];
